import type { RequestHandler } from './$types';
import { getDb } from '$lib/server/db';
import { debugResponse, debugError, validateSqlQuery } from '$lib/server/debug-helpers';
import { sql } from 'drizzle-orm';

/**
 * POST /api/debug/sql
 * Body: { "sql": "SELECT * FROM flights LIMIT 10" }
 *
 * Only SELECT, EXPLAIN, SHOW, DESCRIBE, and WITH (CTE) are allowed.
 * All other statements are rejected with 403.
 * Queries have a 30-second timeout via statement_timeout.
 */
export const POST: RequestHandler = async ({ request }) => {
  const t0 = performance.now();
  try {
    const body = await request.json() as { sql?: string };
    const query = body.sql?.trim();

    if (!query) return debugError('Missing "sql" field in request body', 400);

    // Validate query (SELECT-only, no dangerous keywords)
    const validation = validateSqlQuery(query);
    if (!validation.valid) {
      return debugError(validation.error, 403);
    }

    // Get the underlying pg pool for raw SQL execution
    const d = getDb();

    // Set session-level timeout for this query only, then reset
    await d.execute(sql`SET SESSION statement_timeout = '30s'`);

    let result;
    try {
      result = await d.execute(sql`${sql.raw(query)}`);
    } finally {
      await d.execute(sql`RESET statement_timeout`);
    }

    const queryMs = performance.now() - t0;

    // Log query for audit
    const truncated = query.length > 200 ? query.substring(0, 200) + '...' : query;
    console.log(`[debug/sql] ${queryMs}ms | rows=${result.rows.length} | ${truncated}`);

    return debugResponse(result.rows, queryMs);
  } catch (err) {
    const queryMs = performance.now() - t0;
    const message = err instanceof Error ? err.message : 'Query failed';
    console.error(`[debug/sql] ERROR ${queryMs}ms | ${message}`);
    return debugError(message, 500);
  }
};

import type { RequestHandler } from './$types';
import { db, flights, flightStatusHistory, weatherData, aircraftPositions, flightTimes, airportDaylight } from '$lib/server/db';
import { debugResponse, debugError } from '$lib/server/debug-helpers';
import { eq, desc, and, lte, gte, inArray, isNotNull, asc } from 'drizzle-orm';

/**
 * Mirrors the flight detail load function.
 * GET /api/debug/ui/flight/:id
 */
export const GET: RequestHandler = async ({ params }) => {
  const t0 = performance.now();
  try {
    const id = parseInt(params.id, 10);
    if (isNaN(id)) return debugError('Invalid flight ID', 400);

    const [flight] = await db.select().from(flights).where(eq(flights.id, id)).limit(1);
    if (!flight) return debugError('Flight not found', 404);

    const flightTime = flight.scheduledDeparture;
    const windowStart = new Date(flightTime.getTime() - 90 * 60000);
    const windowEnd   = new Date(Math.max(flightTime.getTime() + 90 * 60000, Date.now()));
    const airports    = [...new Set([flight.departureAirport, flight.arrivalAirport])];

    const depDate = flight.scheduledDeparture.toISOString().split('T')[0];
    const arrDate = flight.scheduledArrival.toISOString().split('T')[0];

    const rotationStart = new Date(flight.scheduledDeparture.getTime() - 24 * 60 * 60 * 1000);
    const rotationFlights = flight.aircraftRegistration
      ? await db.select({
          id: flights.id, flightNumber: flights.flightNumber,
          departureAirport: flights.departureAirport, arrivalAirport: flights.arrivalAirport,
          scheduledDeparture: flights.scheduledDeparture, scheduledArrival: flights.scheduledArrival,
          actualDeparture: flights.actualDeparture, actualArrival: flights.actualArrival,
          status: flights.status, canceled: flights.canceled, delayMinutes: flights.delayMinutes,
        })
        .from(flights)
        .where(and(
          eq(flights.aircraftRegistration, flight.aircraftRegistration),
          gte(flights.scheduledDeparture, rotationStart),
          isNotNull(flights.aircraftRegistration),
        ))
        .orderBy(asc(flights.scheduledDeparture))
      : [];

    const [rawStatusHistory, weatherRows, positionRows, times, daylightRows] = await Promise.all([
      db.select().from(flightStatusHistory)
        .where(eq(flightStatusHistory.flightId, id))
        .orderBy(desc(flightStatusHistory.statusTimestamp)),
      db.select().from(weatherData)
        .where(and(
          inArray(weatherData.airportCode, airports),
          gte(weatherData.timestamp, windowStart),
          lte(weatherData.timestamp, windowEnd),
        ))
        .orderBy(desc(weatherData.timestamp)),
      db.select().from(aircraftPositions)
        .where(eq(aircraftPositions.flightId, id))
        .orderBy(desc(aircraftPositions.positionTimestamp))
        .limit(1),
      db.select().from(flightTimes).where(eq(flightTimes.flightId, id)),
      db.select().from(airportDaylight)
        .where(and(
          inArray(airportDaylight.airportCode, airports),
          inArray(airportDaylight.date, [depDate, arrDate]),
        )),
    ]);

    // WeatherMap — most recent past record per airport
    const weatherMap: Record<string, typeof weatherData.$inferSelect> = {};
    const now = new Date();
    for (const row of weatherRows) {
      const existing = weatherMap[row.airportCode];
      const rowTs = new Date(row.timestamp).getTime();
      if (!existing) { weatherMap[row.airportCode] = row; continue; }
      const existingTs = new Date(existing.timestamp).getTime();
      if (rowTs <= now.getTime() && existingTs > now.getTime()) {
        weatherMap[row.airportCode] = row;
      } else if (rowTs <= now.getTime() && existingTs <= now.getTime() && rowTs > existingTs) {
        weatherMap[row.airportCode] = row;
      }
    }

    // Daylight map
    const daylightMap: Record<string, typeof airportDaylight.$inferSelect[]> = {};
    for (const row of daylightRows) {
      if (!daylightMap[row.airportCode]) daylightMap[row.airportCode] = [];
      daylightMap[row.airportCode].push(row);
    }

    // Deduplicate status history
    const latestGuernseyTs = rawStatusHistory
      .find(e => e.source === 'guernsey_airport')
      ?.statusTimestamp ?? null;
    const seenBySource = new Map<string, Set<string>>();
    const statusHistory = rawStatusHistory.filter((entry) => {
      const key = entry.source;
      if (!seenBySource.has(key)) seenBySource.set(key, new Set());
      const seen = seenBySource.get(key)!;
      if (seen.has(entry.statusMessage)) return false;
      seen.add(entry.statusMessage);
      if (
        entry.source === 'fr24' &&
        entry.statusMessage.toLowerCase().startsWith('estimated dep') &&
        latestGuernseyTs !== null &&
        new Date(latestGuernseyTs) >= new Date(entry.statusTimestamp)
      ) return false;
      return true;
    });

    const data = {
      flight,
      statusHistory,
      weatherMap,
      daylightMap,
      position: positionRows[0] ?? null,
      rotationFlights,
      times,
    };

    return debugResponse([data], performance.now() - t0);
  } catch (err) {
    console.error('[debug/ui/flight]', err);
    return debugError('Query failed', 500);
  }
};

import type { RequestHandler } from './$types';
import { db, flights } from '$lib/server/db';
import { debugResponse, debugError, parsePagination } from '$lib/server/debug-helpers';
import { eq, gte, lte, and, desc, asc, ilike } from 'drizzle-orm';

/**
 * GET /api/debug/flights
 * Query params: date, status, departure_airport, arrival_airport, flight_number,
 *   airline_code, canceled, aircraft_registration, sort, order, limit, offset
 */
export const GET: RequestHandler = async ({ url }) => {
  const t0 = performance.now();

  try {
    const { limit, offset } = parsePagination(url.searchParams);
    const conditions = [];

    // Date filter — matches flight_date
    const dateParam = url.searchParams.get('date');
    if (dateParam) {
      conditions.push(eq(flights.flightDate, dateParam));
    }

    // Date range filter
    const dateFrom = url.searchParams.get('date_from');
    const dateTo = url.searchParams.get('date_to');
    if (dateFrom) conditions.push(gte(flights.flightDate, dateFrom));
    if (dateTo) conditions.push(lte(flights.flightDate, dateTo));

    // Status filter
    const statusParam = url.searchParams.get('status');
    if (statusParam) {
      conditions.push(eq(flights.status, statusParam));
    }

    // Airport filters
    const depAirport = url.searchParams.get('departure_airport');
    if (depAirport) conditions.push(eq(flights.departureAirport, depAirport.toUpperCase()));
    const arrAirport = url.searchParams.get('arrival_airport');
    if (arrAirport) conditions.push(eq(flights.arrivalAirport, arrAirport.toUpperCase()));

    // Flight number — partial match
    const flightNumber = url.searchParams.get('flight_number');
    if (flightNumber) conditions.push(ilike(flights.flightNumber, `%${flightNumber}%`));

    // Airline code
    const airlineCode = url.searchParams.get('airline_code');
    if (airlineCode) conditions.push(eq(flights.airlineCode, airlineCode.toUpperCase()));

    // Canceled flag
    const canceledParam = url.searchParams.get('canceled');
    if (canceledParam !== null) {
      conditions.push(eq(flights.canceled, canceledParam === 'true'));
    }

    // Aircraft registration
    const reg = url.searchParams.get('aircraft_registration');
    if (reg) conditions.push(eq(flights.aircraftRegistration, reg.toUpperCase()));

    // Sorting
    const sortField = url.searchParams.get('sort') ?? 'scheduled_departure';
    const sortOrder = url.searchParams.get('order') === 'asc' ? asc : desc;

    // Map sort field names to Drizzle columns
    const sortColumns: Record<string, typeof flights.scheduledDeparture> = {
      scheduled_departure: flights.scheduledDeparture,
      scheduled_arrival: flights.scheduledArrival,
      actual_departure: flights.actualDeparture,
      actual_arrival: flights.actualArrival,
      delay_minutes: flights.delayMinutes,
      flight_date: flights.flightDate,
      created_at: flights.createdAt,
      updated_at: flights.updatedAt,
    };
    const sortCol = sortColumns[sortField] ?? flights.scheduledDeparture;

    const whereClause = conditions.length > 0 ? and(...conditions) : undefined;

    const rows = conditions.length > 0
      ? await db.select().from(flights).where(whereClause).orderBy(sortOrder(sortCol)).limit(limit).offset(offset)
      : await db.select().from(flights).orderBy(sortOrder(sortCol)).limit(limit).offset(offset);

    const queryMs = performance.now() - t0;
    return debugResponse(rows, queryMs);
  } catch (err) {
    console.error('[debug/flights]', err);
    return debugError('Query failed', 500);
  }
};

